import React, { useState } from 'react';

const AdminPanel = () => {
  // Estado para saber qué pestaña está activa
  const [activeTab, setActiveTab] = useState('Reservas');

  const handleLogout = () => {
    // Aquí puedes borrar el token si lo guardaste en localStorage
    window.location.href = '/login';
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      {/* SIDEBAR */}
      <aside className="sidebar">
        <div className="sidebar-header">
          <h2>Capitania Admin</h2>
        </div>
        <ul className="nav-menu">
          {['Reservas', 'Eventos', 'Promociones'].map((tab) => (
            <li 
              key={tab}
              className={`nav-item ${activeTab === tab ? 'active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </li>
          ))}
        </ul>
      </aside>

      {/* CONTENIDO PRINCIPAL */}
      <main className="main-content">
        <div className="topbar">
          <h1>{activeTab}</h1>
          <button className="btn-logout" onClick={handleLogout}>
            Cerrar Sesión
          </button>
        </div>

        <div className="dashboard-content">
          <h3>Administración de {activeTab}</h3>
          <p>Aquí verás la tabla o formulario de <strong>{activeTab}</strong> próximamente.</p>
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;
